// La pose de reposo tiene que ser idéntica al dibujo base (lo comprueba `pxcli anim check`).
rest(() => {
  draw("base");
});

// Una función por acción: dibuja el frame f desde cero. t va de 0 a 1.
// Ojo redibujado encima de la base: párpados desplazados (au arriba, al abajo),
// brillo del iris (b: -1 deja el de la base, 1 medio, 2 casi blanco), pupila
// (p: 0 normal, 1 estrecha, 2 muy estrecha) y destello blanco.
const CX = 31.5, CY = 34.5, R = 8;
const sup = (x) => {
  const d = Math.abs(x - CX);
  if (d <= 6) return 23;
  if (d <= 9) return 24;
  if (d <= 11) return 25;
  if (d <= 13) return 26;
  if (d <= 15) return 27;
  if (d <= 16.5) return 28;
  if (d <= 18) return 29;
  if (d <= 19) return 30;
  return 31;
};
const inf = (x) => {
  const d = Math.abs(x - CX);
  if (d <= 6.5) return 38;
  if (d <= 9.5) return 37;
  if (d <= 12.5) return 36;
  if (d <= 15.5) return 35;
  if (d <= 17.5) return 34;
  return 33;
};
const enIris = (x, y) => (x - CX) ** 2 + (y - CY) ** 2 <= R * R;

const pupila = (x, y, p) => {
  if (p === 2) {
    if (x === 31 && y >= 31 && y <= 39) return "#1a0722";
    if (x === 32 && y >= 32 && y <= 38) return "#834d37";
    return null;
  }
  if (x === 31 || x === 32) {
    if (p === 0 && y === 30) return "#7a6844";
    if (y >= 31 && y <= (p === 0 ? 40 : 39)) return "#1a0722";
  }
  if (p === 0 && (x === 30 || x === 33) && y >= 33 && y <= 38) return "#1a0722";
  return null;
};

const colorIris = (x, y, b) => {
  const d = Math.hypot(x - CX, y - CY) / R;
  if (d > 0.86) return b >= 2 ? "#f5b632" : y > 36 ? "#e88b10" : "#e47b09";
  if (b >= 2) {
    if (d < 0.4) return "#ffffff";
    if (d < 0.6) return "#fffbd0";
    if (d < 0.75) return "#fff181";
    return "#fdd64b";
  }
  if (b === 1) return d < 0.55 ? "#fff181" : "#fdd64b";
  return y > 38 ? "#f7b621" : "#fdc626";
};

part("ojo", ({ au = 0, al = 0, b = -1, p = 0, blanco = false }) => {
  for (let x = 12; x <= 51; x++) {
    const s = clamp((19.5 - Math.abs(x - CX)) / 5, 0, 1);
    const ou = Math.round(au * s), ol = Math.round(al * s);
    const t0 = sup(x), b0 = inf(x);
    const top = t0 - ou, bot = b0 + ol;
    const interior = Math.abs(x - CX) < 14;
    for (let y = top; y <= bot; y++) {
      const banda_sup = ou > 0 && y <= Math.min(t0 + 5, b0 - 3);
      const banda_inf = ol > 0 && y >= b0 - 2;
      const iris = enIris(x, y) && y > top + 1 && y < bot;
      let c;
      if (y === top || y === bot) {
        if (!banda_sup && !banda_inf) continue;
        c = "#2a0f45";
      } else if (blanco) {
        c = "#ffffff";
      } else if (iris) {
        if (b < 0 && !banda_inf) continue;
        c = pupila(x, y, p) || (b < 0 && y === bot - 1 ? "#c38626" : colorIris(x, y, b));
      } else {
        if (!banda_sup && !banda_inf) continue;
        if (y === top + 1) c = "#754b9c";
        else if (y === bot - 1) c = "#dbb78f";
        else if (y === top + 2) c = interior ? "#d3a5c4" : "#fff4da";
        else if (interior && y <= top + 5) c = "#e6c294";
        else if (y === bot - 2) c = "#f0d6b0";
        else c = "#fff4da";
      }
      set_pixel(x, y, c);
    }
  }
});

action("aviso", { frames: 6, fps: 10, loop: false }, (f, { t }) => {
  base();
  draw("ojo", {
    au: [0, 1, 2, 2, 3, 3][f],
    al: [0, 0, 1, 2, 2, 3][f],
    b: [-1, -1, -1, 1, 2, 2][f],
  });
});

action("disparo", { frames: 4, fps: 12, loop: false }, (f, { t }) => {
  const dy = f === 1 || f === 2 ? -1 : 0;
  move(0, dy, () => {
    base();
    draw("ojo", { au: 3, al: 3, b: 2, p: [1, 2, 2, 1][f], blanco: f === 1 });
  });
});

